generata:
GET COLLECTION centri_logistici;
EXPAND UNPACK TRUE ARRAY .zone_magazzino TO .elemento;
FILTER CASE WHERE .elemento.codice != 'B2';

GET COLLECTION equipments;
FILTER CASE WHERE .storage_location != 'deposito B';
GROUP PARTITION TRUE BY .device_name INTO .risultato;

GET COLLECTION minacce;
FILTER CASE WHERE .tipo_minaccia IS NOT NULL;
GROUP PARTITION TRUE BY .risolta INTO .risultato;

GET COLLECTION cases;
EXPAND UNPACK TRUE ARRAY .items TO .item;
SAVE AS cases_expanded@ft_en_074;
GET COLLECTION cases_expanded@ft_en_074;
JOIN OF COLLECTIONS cases_expanded@ft_en_074 AS a, workers@ft_en_074 AS b CASE WHERE .a.item.worker_id = .b._id;

GET COLLECTION spedizioni;
EXPAND UNPACK TRUE ARRAY .righe TO .elemento;
SAVE AS chaintemp1@ft_it_073;
GET COLLECTION chaintemp1@ft_it_073;
JOIN OF COLLECTIONS chaintemp1@ft_it_073 AS a, ispettori@ft_it_073 AS b CASE WHERE .a.elemento.item.id_ispettori = .b._id;

GET COLLECTION equipments;
FILTER CASE WHERE .storage_location = 'A';
SAVE AS setA@ft_en_078;
GET COLLECTION equipments;
FILTER CASE WHERE .voltage < 194;
SAVE AS setB@ft_en_078;
SUBTRACT COLLECTIONS setA@ft_en_078, setB@ft_en_078;

GET COLLECTION macchinari; FILTER CASE WHERE .codice_modello IS NULL; SAVE AS setA@ft_it_077;
GET COLLECTION macchinari; FILTER CASE WHERE .stato = 'spento'; SAVE AS setB@ft_it_077;
SUBTRACT COLLECTIONS setA@ft_it_077, setB@ft_it_077;
